// Tenant login aliases are generated by the Supabase Edge Functions in
// supabase/functions/_shared/tenantAuthEmail.ts. Keep this helper identical so
// the frontend can recover the alias when an older deployed function returns a
// successful workspace_id but omits login_email.

export function createTenantAuthEmail(contactEmail, workspaceId) {
  const [localPart, domain, extraPart] = String(contactEmail || '')
    .trim()
    .toLowerCase()
    .split('@')

  const tenantTag = String(workspaceId || '').replace(/-/g, '')

  if (!localPart || !domain || extraPart || !tenantTag) {
    return ''
  }

  const suffix = `+${tenantTag}`
  const maxLocalLength = 64 - suffix.length

  if (maxLocalLength <= 0) {
    return ''
  }

  const tenantLocalPart = `${localPart.slice(0, maxLocalLength)}${suffix}`
  const authEmail = `${tenantLocalPart}@${domain}`

  return authEmail.length <= 254 ? authEmail : ''
}
